mapper.select:
SELECT codecd as code, codenm as remark
FROM haba900t_tbl
WHERE cmpycd = #{cmpycd}

    AND cdtype = #{gbncd}


    AND codecd LIKE CONCAT('%', #{code}, '%')

ORDER BY dspord

SELECT cdtype, codecd, codenm, remark, dspord, useyn
FROM haba900t_tbl
WHERE cmpycd = #{cmpycd}

    AND cdtype = #{cdkind}


    AND codecd = #{code}

ORDER BY dspord
